'use strict';
$('#addCampaignBattle').onclick=()=>run(()=>{if(!model.campaign)throw Error('新增战斗需要打开续篇 ROM；原版 ROM 仍可编辑已有战场。');let d=$('#newBattleModal');if(!d){d=document.createElement('dialog');d.id='newBattleModal';document.body.append(d);}const cs=model.campaignData().chapters;d.innerHTML=`<div class="modalhead"><h2>新增一场战斗</h2><button id="closeNewBattle">✕</button></div><p>复制一张可用地图和出场配置，再修改人物、目标与剧情。</p><label>战斗名称<input id="newBattleTitle" value="新的木叶任务" maxlength="100"></label><label>从哪场复制地图和配置<select id="newBattleTemplate">${opts(model.battleIds().map(s=>[s,model.campaignData().chapters.find(c=>c.id===s)?.title||`原版战场 ${s}`]),cs.at(-1).id)}</select></label><label>安排在哪场战斗之后<select id="newBattlePrevious">${opts(cs.map(c=>[c.id,c.title]),cs.at(-1).id)}</select></label><p class="hint">会插入到所选战斗之后，完成后继续原来的下一场。最多保留 48 个新增战斗位置。</p><button id="createNewBattle" class="primary">创建并编辑</button>`;$('#closeNewBattle').onclick=()=>d.close();$('#createNewBattle').onclick=()=>run(()=>{let id;transaction('新增战斗',()=>{id=model.addCampaignBattle($('#newBattleTitle').value,+$('#newBattleTemplate').value,+$('#newBattlePrevious').value);},false);d.close();initializeFlow();selectFlow(flowItems.find(c=>c.scene===id&&c.kind==='battle'));});d.showModal();});
const nativeRenderDialogue=renderDialogue;
renderDialogue=function(){const battle=model.newBattlePages(stage);if(!battle)return nativeRenderDialogue();panel.innerHTML=`<div class="sectionhead"><div><h2>${esc(battle.title)} · 新增剧情</h2><p>选择说话人并填写内容，可添加多段对白。</p></div><button id="saveNewPages" class="primary">保存战前与战后剧情</button></div>${[['before','战前剧情'],['after','战后剧情']].map(([kind,title])=>`<div class="card newCampaignPages" data-kind="${kind}"><h3>${title}</h3><div class="newPageRows">${battle[kind].map(p=>newPageRow(p)).join('')}</div><button class="addCampaignPage">增加对白</button></div>`).join('')}<p class="notice">长对白可使用【分页】；建议每行 24 字、每页 2 行。导出新 ROM 后，新战场会和已有战场一样显示在普通剧情编辑页。</p>`;for(const card of panel.querySelectorAll('.newCampaignPages')){card.querySelector('.addCampaignPage').onclick=()=>{card.querySelector('.newPageRows').insertAdjacentHTML('beforeend',newPageRow({speaker:1,text:'新的对白。'}));wireNewPageRows(card);};wireNewPageRows(card);}$('#saveNewPages').onclick=()=>run(()=>{const get=kind=>[...panel.querySelector(`[data-kind=${kind}]`).querySelectorAll('.newCampaignPage')].map(r=>({speaker:+r.querySelector('select').value,text:r.querySelector('textarea').value}));transaction('编辑新增战斗剧情',()=>model.setNewBattlePages(stage,get('before'),get('after')));});};
function newPageRow(p){return `<div class="newCampaignPage eventpage"><label>说话人<select>${opts([[0,'旁白'],...assetTargetIds()],p.speaker)}</select></label><textarea rows="3">${esc(p.text)}</textarea><div class="toolbar"><button class="wrapNewPage">自动分页</button><button class="removeNewPage">删除对白</button></div></div>`;}
function wireNewPageRows(card){card.querySelectorAll('.newCampaignPage').forEach(r=>{r.querySelector('.removeNewPage').onclick=()=>r.remove();r.querySelector('.wrapNewPage').onclick=()=>run(()=>{r.querySelector('textarea').value=paginateEvent(r.querySelector('textarea').value);});});}
